public static int finalGrade(int[] a, int[] b, int[] answers) {
    int grade = 0;
    for (int i = 0; i < a.length; i++) {
        if (answers[i] == a[i] + b[i]) {
            grade = grade + 10;
        }
    }
    return grade;
}

public static boolean passed(int grade) {
    return grade > 54;
}

