public static String check(Object got, Object expected) {
    String g = String.valueOf(got).trim();
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
int[] a = { 67, 25, 48, 90, 12, 33, 71, 5, 56, 19 };
int[] b = { 13, 40, 27, 8, 64, 49, 18, 77, 30, 81 };
System.out.println("סעיף א, בדיקה 1 (הדוגמה): " + check(finalGrade(a, b, new int[] { 80, 65, 74, 98, 76, 72, 89, 82, 85, 100 }), 70));
System.out.println("סעיף א, בדיקה 2 (כל התשובות נכונות): " + check(finalGrade(a, b, new int[] { 80, 65, 75, 98, 76, 82, 89, 82, 86, 100 }), 100));
System.out.println("סעיף א, בדיקה 3 (כל התשובות שגויות): " + check(finalGrade(a, b, new int[] { 81, 66, 76, 99, 77, 83, 90, 83, 87, 101 }), 0));
System.out.println("סעיף א, בדיקה 4 (נכון רק בתרגיל הראשון ובאחרון): " + check(finalGrade(a, b, new int[] { 80, 66, 76, 99, 77, 83, 90, 83, 87, 100 }), 20));
System.out.println("סעיף ב, בדיקה 1 (ציון 70): " + check(passed(70), true));
System.out.println("סעיף ב, בדיקה 2 (ציון 50): " + check(passed(50), false));
System.out.println("סעיף ב, בדיקה 3 (ציון 54 — נכשל): " + check(passed(54), false));
System.out.println("סעיף ב, בדיקה 4 (ציון 55 — עובר): " + check(passed(55), true));

